// Deklarasi variabel
const $tabelData = $('#tabelData'),
    $formData = $('#formData'),
    $modalDiv = $('#modalDiv'),
    formCek = CirebonwebForm.FormCek($formData);

$(function () {
    $tabelData.DataTable({
        processing: true,
        serverSide: true,
        ajax: {
            url: `${thisUrl}/tabel`,
            type: 'POST',
            data: function (d) {
                d.filter_nota = $('#filter_nota').val();
                d.filter_barang = $('#filter_barang').val();
            }
        },
        autoWidth: false,
        responsive: true,
        order: [[0, 'desc']],
        search: { return: true },
        dom: 'Blfrtip',
        buttons: [
            // { text: 'Add', action: () => { window.location.href = `${thisUrl}/isi?add`; } },
            { text: 'Add', action: () => { simpan(); } },
            {
                text: 'Reload',
                action: function (e, dt, node, config) {
                    dt.search('').draw();
                    $('#filter_nota, #filter_barang').val('').trigger('change');
                    Swal.fire({ icon: 'success', title: 'Informasi', text: 'Selesai reload tabel ke kondisi awal', showConfirmButton: false, timer: 1300 })
                        .then(function () { dt.ajax.reload(null, true); });
                }
            },
            { extend: 'excelHtml5', exportOptions: { columns: ':not(.no-export)', orthogonal: 'export' } }
        ],
        columnDefs: [
            { targets: '_all', className: 'dt-head-center' },
            { targets: [0, 1, 8, 9], className: 'dt-body-center' },
            { targets: [3, 4, 5, 6, 7], className: 'dt-body-right', orderable: false },
            {
                targets: [3, 4, 5, 6, 7], render: CirebonwebFormat.RupiahTabel
            },
            { targets: [1, 10, 14, 15], render: (data) => CirebonwebFormat.Tanggal(data) },
        ]
    });

    // Custom dropdown filter
    $('#tabelData_filter.dataTables_filter').append($('#filter_nota, #filter_barang'));
    $(document).on('change', '#filter_nota, #filter_barang', function () {
        $tabelData.DataTable().ajax.reload(null, false);
    });

    // Input tanggal
    $('.tanggal').datepicker({
        dateFormat: 'dd-mm-yy'
    });

    $formData.find('#status_barang').on('change', function () {
        if ($(this).val() === '1' && !$formData.find('#tgl_ambil').val()) {
            $formData.find('#tgl_ambil').val(CirebonwebFormat.Tanggal(new Date(), 'tanggal'));
        }
        if ($(this).val() === '0') {
            $formData.find('#tgl_ambil').val('');
        }
    });

    // Fokus select2 input
    $(document).on('select2:open', () => document.querySelector('.select2-container--open .select2-search__field')?.focus());

    // Reset Modal
    $modalDiv.on('shown.bs.modal', function () {
        $('.select2').select2({ tags: true, dropdownParent: $modalDiv });
        formCek.resetInitial();
    }).on('hidden.bs.modal', function () {
        CirebonwebForm.FormReset(this);
        $('.select2.select2-hidden-accessible').select2('destroy');
    });

    // Event pilih konsumen
    $formData.on('change', '#konsumen_id', function () {
        const opt = $(this).find(':selected');
        $formData.find('#konsumen_tipe').val(opt.data('tipe') || 'Retail');
    });
});

function simpan(id) {
    const isEdit = id > 0;

    const $modalTitle = $('.modal-title'),
        $btnSubmit = $('#btnSubmit'),
        postUrl = `${thisUrl}/simpan`;

    if (isEdit) {
        CirebonwebForm.FormFetch(`${thisUrl}/getid`, { id }, 'POST', {})
            .done(function (response) {
                if (response.success) {
                    const data = response.data;
                    $modalTitle.text('Edit Data');
                    $btnSubmit.text('Update');

                    $formData.find('#id').val(data.id);
                    $formData.find('#konsumen_id').val(data.konsumen_id).trigger('change');
                    CirebonwebFormat.isoTanggal('tgl_nota', data.tgl_nota);
                    $formData.find('#no_nota').val(data.no_nota);
                    $formData.find('#nettotal').val(CirebonwebFormat.Rupiah(data.nettotal));
                    $formData.find('#bayar').val(CirebonwebFormat.Rupiah(data.bayar));
                    $formData.find('#sisa').val(CirebonwebFormat.Rupiah(data.sisa));
                    const statusNota = ['Belum Bayar', 'Belum Lunas', 'Lunas', 'Hapus Nota'];
                    $formData.find('#status_nota').val(statusNota[data.status_nota] || '-');
                    $formData.find('#status_barang').val(data.status_barang);
                    CirebonwebFormat.isoTanggal('tgl_ambil', data.tgl_ambil);
                    $formData.find('#keterangan').val(data.keterangan);
                    $modalDiv.modal('show');
                }
            });
    } else {
        $modalTitle.text('Tambah Data');
        $btnSubmit.text('Simpan');
        $formData.find('#tgl_nota').val(CirebonwebFormat.Tanggal(new Date(), 'tanggal'));
        $modalDiv.modal('show');
    }

    $formData.validate($.extend(CirebonwebForm.FormValidasi(), {
        rules: {
            tgl_nota: { required: true },
            keterangan: { maxlength: 255 }
        },

        submitHandler: function () {
            if (!formCek.isChanged()) return false;

            const tglNota = CirebonwebFormat.sqlTanggal($formData.find('#tgl_nota').val());
            const tglAmbil = $formData.find('#tgl_ambil').val()
                ? CirebonwebFormat.sqlTanggal($formData.find('#tgl_ambil').val())
                : '';
            if (!tglNota || ($formData.find('#tgl_ambil').val() && !tglAmbil)) {
                $formData.validate().showErrors({
                    tgl_nota: 'Gunakan format tanggal dd-mm-yyyy yang valid.',
                    tgl_ambil: 'Gunakan format tanggal dd-mm-yyyy yang valid.'
                });
                return false;
            }

            const formData = $formData.serializeArray().map((item) => {
                if (item.name === 'tgl_nota') {
                    item.value = tglNota;
                } else if (item.name === 'tgl_ambil') {
                    item.value = tglAmbil;
                }
                return item;
            });

            CirebonwebForm.FormFetch(postUrl, formData, 'POST', {
                before_call: function () {
                    if (!formCek.isChanged()) return false;

                    $btnSubmit
                        .attr('disabled', true)
                        .html('<span class="spinner-border spinner-border-sm mr-1"></span> Loading...');
                },

                after_call: function () {
                    $btnSubmit.attr('disabled', false).html('Simpan');
                }
            })
                .done(function (response) {
                    if (!response.success) return;
                    $modalDiv.modal('hide');
                    Swal.fire({ icon: 'success', title: 'Sukses', html: response.messages, showConfirmButton: false, timer: 1300 })
                        .then(function () {
                            if (!isEdit) {
                                window.location.href = `${thisUrl}/isi?edit=${response.data.id}`;
                            } else {
                                $tabelData.DataTable().ajax.reload(null, false);
                            }
                        });
                });

            return false;
        }
    }));
}
